// Validate GeoJSON from Node 9
const result = $input.first().json;
const geojson = result.geojson_output;

if (!geojson) throw new Error('[VALIDATION] geojson_output is null — query returned no data');
if (geojson.type !== 'FeatureCollection') throw new Error('[VALIDATION] Root type is not FeatureCollection');
if (!Array.isArray(geojson.features)) throw new Error('[VALIDATION] features is not an array');

const featureCount = geojson.features.length;
if (featureCount === 0) throw new Error('[VALIDATION] GeoJSON has 0 features');
if (featureCount !== 296) console.warn(`[VALIDATION] WARNING: expected 296 features, got ${featureCount}`);

const nullGeoms = geojson.features.filter(f => !f.geometry).length;
if (nullGeoms > 0) throw new Error(`[VALIDATION] ${nullGeoms} features have NULL geometries`);

const runId = geojson.metadata?.run_id || 'unknown';
const sizeKB = (JSON.stringify(geojson).length / 1024).toFixed(1);

console.log(`[VALIDATION] ✓ features=${featureCount} | run_id=${runId} | size=${sizeKB}KB | null_geoms=0`);

return [{
  json: {
    geojson: geojson,
    run_id: runId,
    feature_count: featureCount,
    size_kb: parseFloat(sizeKB),
    validated_at: new Date().toISOString()
  }
}];

// Publish GeoJSON and signals JSON to GitHub
const input = $input.first().json;
const geojson = input.geojson;
const runId = input.run_id;
const GITHUB_TOKEN = $env.GITHUB_TOKEN;
const GITHUB_REPO = $env.GITHUB_REPO || 'slendeavours/ONS_Population_Estimates';
const GITHUB_BRANCH = $env.GITHUB_BRANCH || 'main';

if (!GITHUB_TOKEN) throw new Error('[GITHUB_PUBLISH] GITHUB_TOKEN env var not set');

async function upsertFile(path, content, message) {
  const apiUrl = `https://api.github.com/repos/${GITHUB_REPO}/contents/${path}`;
  const encoded = Buffer.from(content).toString('base64');
  let sha = null;
  try {
    const getRes = await fetch(apiUrl, {
      headers: { 'Authorization': `token ${GITHUB_TOKEN}`, 'Accept': 'application/vnd.github.v3+json' }
    });
    if (getRes.ok) { const d = await getRes.json(); sha = d.sha; }
  } catch (e) { /* file does not exist */ }

  const body = { message, content: encoded, branch: GITHUB_BRANCH };
  if (sha) body.sha = sha;

  const putRes = await fetch(apiUrl, {
    method: 'PUT',
    headers: {
      'Authorization': `token ${GITHUB_TOKEN}`,
      'Accept': 'application/vnd.github.v3+json',
      'Content-Type': 'application/json'
    },
    body: JSON.stringify(body)
  });

  if (!putRes.ok) {
    const err = await putRes.json();
    throw new Error(`GitHub API ${putRes.status}: ${JSON.stringify(err)}`);
  }
  return await putRes.json();
}

// Note: For files > 1MB, use git push (Git Data API required)
// The signals JSON (~172KB) can use the Contents API directly
// The GeoJSON (~9.5MB) MUST be pushed via git (see Methodology)

// Publish signals-only JSON (lightweight, works via Contents API)
const signals = geojson.features.map(f => f.properties);
const signalsPayload = {
  metadata: {
    generated_at: new Date().toISOString(),
    run_id: runId,
    feature_count: signals.length.toString(),
    source: 'exempt_pipeline'
  },
  signals: signals
};

const signalsResult = await upsertFile(
  'data/signals/staging_la_signals_latest.json',
  JSON.stringify(signalsPayload),
  `Update signals — run ${runId} — ${new Date().toISOString()}`
);
console.log(`[GITHUB_PUBLISH] ✓ signals published: ${signalsResult.content?.html_url}`);

// Publish metadata
const metadata = {
  generated_at: new Date().toISOString(),
  run_id: runId,
  feature_count: geojson.features.length
};
const metaResult = await upsertFile(
  'data/signals/latest.json',
  JSON.stringify(metadata, null, 2),
  `Update metadata — run ${runId}`
);
console.log(`[GITHUB_PUBLISH] ✓ metadata published: ${metaResult.content?.html_url}`);

// For the large GeoJSON, this node writes it to the shared volume
// The git push for the GeoJSON must be handled by a separate shell script or Docker exec
// See METHODOLOGY.md for the full automation approach

console.log(`[GITHUB_PUBLISH] ✓ run_id=${runId} | signals and metadata published to GitHub`);
console.log(`[GITHUB_PUBLISH] NOTE: GeoJSON (9.5MB) requires git push — use scripts/export.js + git commit/push`);

const rawBase = `https://raw.githubusercontent.com/${GITHUB_REPO}/${GITHUB_BRANCH}`;
return [{
  json: {
    published: true,
    run_id: runId,
    signals_url: `${rawBase}/data/signals/staging_la_signals_latest.json`,
    metadata_url: `${rawBase}/data/signals/latest.json`,
    geojson_url: `${rawBase}/data/boundaries/la_boundaries.geojson`,
    published_at: new Date().toISOString()
  }
}];

